arguments.playbook_status:
{%- set apiret = vars.steps.create_connector_config -%}

{# Default status is ok #}
{%- set s = {
  "error":false,
  "status":"Ok",
  "message":"Connector Built without Error."
} -%}

{# Catch Any issues below #}
{%- if apiret.data.status.status is not defined -%}
  {%-do s.update({
    "error":true,
    "status":"Failed",
    "message":"Connector Config Status Missing."
  }) -%}
{%- elif apiret.data.status.status != "finished" -%}
  {%-do s.update({
    "error":true,
    "status":"Failed",
    "message":"Connector Config Failed.\n" + apiret.data.status.message
  }) -%}
{%- else -%}
  {%-do s.update({
    "message": apiret.data.status.message
  }) -%}
{%- endif -%}

{{s}}
